\[[ABC] = \frac{1}{2} AC \cdot BC \cdot \sin C.\][asy]
unitsize (1 cm);

pair A, B, C, D;

A = (0,0);
B = (5,0);
C = (1,2);
D = extension(C, incenter(A,B,C), A, B);

draw(A--B--C--cycle);
draw(C--D);

label("$A$", A, SW);
